import json
import re
from typing import Dict, Any, Optional
from dataclasses import dataclass, field
from pymongo import MongoClient
import hashlib


@dataclass
class TenantContext:
    tenant_id: str
    namespace: str
    permissions: list = field(default_factory=list)


class SolidityABISerializer:
    """Serializes Solidity ABI-encoded data for multi-tenant storage."""

    SOLIDITY_TYPES = {
        'uint256': 32, 'int256': 32, 'address': 20,
        'bytes32': 32, 'bool': 1, 'string': None
    }

    def __init__(self, mongo_uri: str = "mongodb://localhost:27017"):
        self.client = MongoClient(mongo_uri)
        self.db = self.client['solidity_store']

    def _compute_slot_key(self, contract_addr: str, slot: int, tenant: TenantContext) -> str:
        """Compute storage slot key with tenant isolation."""
        raw = f"{tenant.namespace}:{contract_addr}:{slot}"
        return hashlib.sha256(raw.encode()).hexdigest()

    def _validate_tenant_namespace(self, namespace: str) -> bool:
        """Validate tenant namespace format."""
        pattern = r'^[a-zA-Z0-9_\-\.]+$'
        return bool(re.match(pattern, namespace))

    def _build_isolation_filter(self, tenant: TenantContext, extra_filter: Optional[Dict] = None) -> Dict:
        """Build MongoDB query filter with tenant isolation.

        Ensures queries are scoped to the tenant's namespace.
        The extra_filter allows additional query refinement.
        """
        base_filter = {"tenant_ns": tenant.namespace}

        if extra_filter:
            # Merge filters - tenant namespace is always enforced
            merged = {**base_filter, **extra_filter}
            # Re-apply tenant constraint after merge to prevent override
            merged["tenant_ns"] = tenant.namespace
            return merged

        return base_filter

    def serialize_slot(self, contract_addr: str, slot: int, 
                       value: bytes, sol_type: str, tenant: TenantContext) -> str:
        """Serialize a Solidity storage slot value."""
        if not self._validate_tenant_namespace(tenant.namespace):
            raise ValueError("Invalid tenant namespace")

        if sol_type not in self.SOLIDITY_TYPES:
            raise ValueError(f"Unsupported Solidity type: {sol_type}")

        slot_key = self._compute_slot_key(contract_addr, slot, tenant)

        doc = {
            "slot_key": slot_key,
            "contract": contract_addr,
            "slot": slot,
            "value": value.hex(),
            "sol_type": sol_type,
            "tenant_ns": tenant.namespace
        }

        self.db.storage_slots.update_one(
            {"slot_key": slot_key, "tenant_ns": tenant.namespace},
            {"$set": doc},
            upsert=True
        )
        return slot_key

    def query_slots(self, tenant: TenantContext, query_params: Dict[str, Any]) -> list:
        """Query storage slots with tenant-scoped filtering.

        query_params supports:
          - contract: filter by contract address
          - sol_type: filter by Solidity type
          - slot_range: dict with 'min' and 'max' for slot range queries
        """
        if not self._validate_tenant_namespace(tenant.namespace):
            raise ValueError("Invalid tenant namespace")

        query_filter = {}

        if 'contract' in query_params:
            contract = query_params['contract']
            if isinstance(contract, str) and re.match(r'^0x[a-fA-F0-9]{40}$', contract):
                query_filter['contract'] = contract

        if 'sol_type' in query_params:
            sol_type = query_params['sol_type']
            if isinstance(sol_type, str) and sol_type in self.SOLIDITY_TYPES:
                query_filter['sol_type'] = sol_type

        if 'slot_range' in query_params:
            slot_range = query_params['slot_range']
            if isinstance(slot_range, dict):
                slot_query = {}
                if 'min' in slot_range:
                    slot_query['$gte'] = int(slot_range['min'])
                if 'max' in slot_range:
                    slot_query['$lte'] = int(slot_range['max'])
                if slot_query:
                    query_filter['slot'] = slot_query

        # Apply tenant isolation
        final_filter = self._build_isolation_filter(tenant, query_filter)

        results = list(self.db.storage_slots.find(final_filter, {'_id': 0}))
        return results

    def batch_deserialize(self, tenant: TenantContext, slot_keys: list,
                          projection: Optional[Dict] = None) -> list:
        """Batch retrieve and deserialize storage slots.

        projection allows selecting specific fields to return.
        """
        if not self._validate_tenant_namespace(tenant.namespace):
            raise ValueError("Invalid tenant namespace")

        # Validate slot_keys are hex strings
        validated_keys = []
        for key in slot_keys:
            if isinstance(key, str) and re.match(r'^[a-f0-9]{64}$', key):
                validated_keys.append(key)

        if not validated_keys:
            return []

        lookup_filter = {
            "slot_key": {"$in": validated_keys},
            "tenant_ns": tenant.namespace
        }

        # Build projection - always exclude _id, include tenant_ns for verification
        safe_projection = {'_id': 0, 'tenant_ns': 1}
        if projection:
            for field_name, include in projection.items():
                if isinstance(field_name, str) and field_name != '_id':
                    safe_projection[field_name] = include

        results = list(self.db.storage_slots.find(lookup_filter, safe_projection))
        return results

    def aggregate_by_type(self, tenant: TenantContext, group_config: Dict) -> list:
        """Aggregate storage data grouped by Solidity type.

        group_config controls aggregation behavior:
          - include_values: bool, whether to include actual values
          - type_filter: list of sol_types to include
        """
        if not self._validate_tenant_namespace(tenant.namespace):
            raise ValueError("Invalid tenant namespace")

        match_stage = {"$match": {"tenant_ns": tenant.namespace}}

        if 'type_filter' in group_config:
            type_filter = group_config['type_filter']
            if isinstance(type_filter, list):
                valid_types = [t for t in type_filter if t in self.SOLIDITY_TYPES]
                if valid_types:
                    match_stage["$match"]["sol_type"] = {"$in": valid_types}

        group_stage = {
            "$group": {
                "_id": "$sol_type",
                "count": {"$sum": 1}
            }
        }

        if group_config.get('include_values', False):
            group_stage["$group"]["values"] = {"$push": "$value"}

        pipeline = [match_stage, group_stage]

        # Allow custom sort if specified
        if 'sort' in group_config:
            sort_spec = group_config['sort']
            if isinstance(sort_spec, dict):
                pipeline.append({"$sort": sort_spec})

        results = list(self.db.storage_slots.aggregate(pipeline))
        return results

    def delete_contract_data(self, tenant: TenantContext, contract_addr: str,
                             condition: Optional[Dict] = None) -> int:
        """Delete all storage data for a contract within tenant scope."""
        if not self._validate_tenant_namespace(tenant.namespace):
            raise ValueError("Invalid tenant namespace")

        if not re.match(r'^0x[a-fA-F0-9]{40}$', contract_addr):
            raise ValueError("Invalid contract address")

        delete_filter = {
            "contract": contract_addr,
            "tenant_ns": tenant.namespace
        }

        if condition:
            # Allow conditional deletion (e.g., only slots of certain type)
            for key, val in condition.items():
                if key not in ('contract', 'tenant_ns'):
                    delete_filter[key] = val

        result = self.db.storage_slots.delete_many(delete_filter)
        return result.deleted_count
